'use strict';
const APP='year9-week5-helpdesk-improvement', teacher=new URLSearchParams(location.search).has('teacher'), STORAGE_BASE=APP+'-v2';
const notebookKey=name=>STORAGE_BASE+'-'+(teacher?'teacher':String(name||'guest').toLowerCase().replace(/[^a-z0-9]/g,''));
let storageKey=teacher?notebookKey('teacher'):(localStorage.getItem(STORAGE_BASE+'-last')||notebookKey('guest'));
const app=document.getElementById('app'), noticeBox=document.getElementById('notice');
const T=(en,ms,zh)=>({en,ms,zh});
const tx=x=>typeof x==='string'?x:(x?.[state.lang]||x?.en||'');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paras=x=>`<p>${esc(tx(x))}</p>`;
const LANGS={en:'English',ms:'Bahasa Melayu',zh:'简体中文'};
const initial=()=>({name:'',className:'',lang:'en',page:'read',guided:false,answers:{},first:{},checked:{},code:{main:SCAFFOLD,challenge:''},runs:[],tests:{},phase:{},tutor:0,order:[2,0,3,1],orderChecked:false,started:false});
let state=initial(),entry=true,live=null,batch=null,saveOK=true;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&saved.app===APP&&saved.state){state={...initial(),...saved.state};state.answers=state.answers||{};state.first=state.first||{};state.checked=state.checked||{};state.code=state.code||{};state.runs=Array.isArray(state.runs)?state.runs:[];state.tests=state.tests||{};state.phase=state.phase||{};state.order=Array.isArray(state.order)?state.order:[2,0,3,1];entry=!state.started;}}catch{}
if(teacher){state.guided=new URLSearchParams(location.search).has('guided');}
function save(){try{localStorage.setItem(storageKey,JSON.stringify({app:APP,state}));saveOK=true;}catch{saveOK=false;}}
function say(x){noticeBox.textContent=tx(x);noticeBox.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>noticeBox.classList.remove('show'),4500);}
function guidedScaffold(){return SCAFFOLD.replace('if False:\n            print("Bad input")','if people_ahead < 0 or minutes_available < 0:\n            print("Bad input")').replace('total_minutes = 0','total_minutes = (people_ahead + 1) * MINUTES_PER_PERSON');}
function matchKai(name){return String(name).toLowerCase().replace(/[^a-z]/g,'').includes('ngjunkai');}
function langSelect(){return `<label class="language"><span>${esc(tx(T('Language','Bahasa','语言')))}</span><select id="language">${Object.entries(LANGS).map(([k,v])=>`<option value="${k}" ${state.lang===k?'selected':''}>${v}</option>`).join('')}</select></label>`;}
function aimCards(){return `<div class="aim-banner"><span class="eyebrow">WAGBA</span><p>${esc(tx(LESSON.wagba))}</p></div><div class="aims"><div><b class="aim-letter">K</b><b>${esc(tx(T('Knowledge','Pengetahuan','知识')))}</b>${paras(LESSON.knowledge)}</div><div><b class="aim-letter">S</b><b>${esc(tx(T('Skills','Kemahiran','技能')))}</b>${paras(LESSON.skills)}</div><div><b class="aim-letter">U</b><b>${esc(tx(T('Understanding','Pemahaman','理解')))}</b>${paras(LESSON.understanding)}</div></div>`;}
function landing(){return `<main id="main" class="landing"><header><b class="brand">CS / MR DAVE</b>${langSelect()}</header><div class="landing-grid"><section><span class="eyebrow">${esc(tx(T('YEAR 9 · PYTHON PROJECT','TAHUN 9 · PROJEK PYTHON','九年级 · PYTHON 项目')))}</span><h1>${esc(tx(LESSON.title))}<span class="dot">.</span></h1><p class="intro">${esc(tx(T('Sam needs a helpful answer, even when someone types the wrong thing. Build, test and improve his adviser.','Sam memerlukan jawapan yang membantu, walaupun seseorang menaip sesuatu yang salah. Bina, uji dan perbaiki penasihatnya.','即使有人输入错误内容，Sam 仍需要有用的建议。编写、测试并改进这个程序。')))}</p>${aimCards()}</section><form id="entry" class="card entry-card"><span class="pill">${esc(tx(T('Your lesson','Pelajaran anda','你的课程')))}</span><h2>${esc(tx(T('Open your workspace','Buka ruang kerja','打开学习空间')))}</h2><label>${esc(tx(T('Full name','Nama penuh','姓名')))}<input name="name" maxlength="100" autocomplete="name" required value="${esc(state.name)}"></label><label>${esc(tx(T('Class','Kelas','班级')))}<input name="className" maxlength="60" required value="${esc(state.className)}"></label><button class="primary full" type="submit">${esc(tx(T('Start lesson','Mulakan pelajaran','开始课程')))} →</button><p class="small">${esc(tx(T('Your work saves in this browser. Save a backup if you will use another device.','Kerja anda disimpan dalam pelayar ini. Simpan sandaran jika anda akan menggunakan peranti lain.','作品保存在此浏览器。如要换设备，请保存备份。')))}</p>${teacher?`<span class="teacher-tag">${esc(tx(T('Teacher preview','Pratonton guru','教师预览')))}</span>`:''}<label class="file-label">${esc(tx(T('Load a saved backup','Muatkan sandaran','加载已保存的备份')))}<input id="restore" type="file" accept="application/json,.json"></label></form></div></main>`;}
function nav(){let last='';return PAGES.map(([id,label,group],i)=>`${group!==last?(last=group,`<p class="nav-group">${esc(tx(GROUPS[group]))}</p>`):''}<button data-page="${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-dot"></span>${esc(tx(label))}<small>${String(i+1).padStart(2,'0')}</small></button>`).join('');}
function shell(){let index=PAGES.findIndex(p=>p[0]===state.page);if(index<0){state.page='read';index=0;}const page=PAGES[index];return `<div class="shell"><aside class="sidebar"><b class="brand">CS / MR DAVE</b><p class="course">${esc(tx(T('Year 9 · Helpdesk project','Tahun 9 · Projek meja bantuan','九年级 · 服务台项目')))}</p><details class="lesson-menu" open><summary>${esc(tx(T('Lesson pages','Halaman pelajaran','课程页面')))}</summary><nav>${nav()}</nav></details><details class="sidebar-aims" open><summary>${esc(tx(T('Today’s learning','Pembelajaran hari ini','今天的学习')))}</summary>${aimCards()}</details></aside><div class="workspace"><header class="topbar"><div><b>${esc(state.name)}</b><small>${esc(state.className)} · ${saveOK?esc(tx(T('Saved in this browser','Disimpan dalam pelayar ini','已保存在此浏览器'))):esc(tx(T('Save a backup','Simpan sandaran','请保存备份')))}</small></div><div class="top-actions">${langSelect()}${state.guided?`<span class="pill">${esc(tx(T('Step by step · 简短回答','Langkah demi langkah · 简短回答','一步一步 · 简短回答')))}</span>`:''}${teacher?`<button id="toggle-guided">${esc(tx(state.guided?T('Standard preview','Pratonton biasa','普通预览'):T('Supported preview','Pratonton sokongan','辅助预览')))}</button>`:''}<button id="home">${esc(tx(T('Welcome','Selamat datang','欢迎页')))}</button></div></header><main id="main"><div class="page-heading"><div><span class="eyebrow">${esc(tx(GROUPS[page[2]]))}</span><h1 id="page-title" tabindex="-1">${esc(tx(page[1]))}</h1></div><span class="page-count">${index+1} / ${PAGES.length}</span></div>${state.guided?`<div class="support-strip">${esc(tx(T('One step at a time. Choose an answer first; short English is enough. 一步一步来。','Satu langkah pada satu masa. Pilih jawapan dahulu; ayat pendek memadai. 一步一步来。','一步一步来。先选择答案，简短英语就够了。')))}</div>`:''}${pageContent()}<footer class="page-footer"><button data-page="${PAGES[Math.max(0,index-1)][0]}" ${index===0?'disabled':''}>← ${esc(tx(T('Back','Kembali','返回')))}</button><span>${esc(tx(page[1]))}</span>${index<PAGES.length-1?`<button class="primary" data-page="${PAGES[index+1][0]}">${esc(tx(T('Next page','Halaman seterusnya','下一页')))} →</button>`:''}</footer></main></div></div>`;}
function render(){document.documentElement.lang=state.lang==='zh'?'zh-Hans':state.lang;app.innerHTML=entry?landing():shell();if(!entry&&['main1','main2','challenge'].includes(state.page))syncEditor();}
function pageContent(){switch(state.page){case'read':return readPage();case'starter':return starterPage();case'types':return typesPage();case'main1':return main1Page();case'main2':return main2Page();case'challenge':return challengePage();case'pit':return pitPage();case'plenary':return plenaryPage();default:return '';}}
function card(title,body,kind=''){return `<section class="card ${kind}"><h2>${esc(tx(title))}</h2>${body}</section>`;}
const TUTOR_LINES=[
 'answer = input("Number of tickets: ")',
 'try:',
 '    tickets = int(answer)',
 '    if tickets < 0:',
 '        print("Enter zero or more.")',
 '    else:',
 '        if tickets == 0:',
 '            print("No tickets to check.")',
 '        else:',
 '            print("Check each ticket.")',
 'except ValueError:',
 '    print("Enter a whole number.")'
];
const TUTOR_NOTES=[
 T('Ask the user. input() stores their answer as text.','Tanya pengguna. input() menyimpan jawapan sebagai teks.','向用户提问。input() 把回答保存为文字。'),
 T('try begins the code that may fail when text is converted.','try memulakan kod yang mungkin gagal semasa menukar teks.','try 开始可能在文字转换时出错的代码。'),
 T('int() tries to turn the text into a whole number.','int() cuba menukar teks kepada nombor bulat.','int() 尝试将文字转成整数。'),
 T('The outer decision checks for an impossible negative number.','Keputusan luar memeriksa nombor negatif yang mustahil.','外层判断检查不合理的负数。'),
 T('If negative, give a correction. Do not calculate advice.','Jika negatif, beri pembetulan. Jangan kira nasihat.','如果是负数，给出纠正提示，不计算建议。'),
 T('Only a valid number moves into the else branch.','Hanya nombor sah masuk ke cabang else.','只有有效数字会进入 else 分支。'),
 T('This inner decision runs only for a valid number.','Keputusan di dalam ini hanya berjalan untuk nombor sah.','这个内层判断只在数字有效时运行。'),
 T('Zero tickets gives its own output.','Sifar tiket menghasilkan output tersendiri.','零张票会得到单独的输出。'),
 T('Otherwise there is at least one ticket.','Jika tidak, terdapat sekurang-kurangnya satu tiket.','否则至少有一张票。'),
 T('Give the matching advice.','Berikan nasihat yang sesuai.','给出相应建议。'),
 T('If int() cannot convert the text, run this error route.','Jika int() tidak boleh menukar teks, jalankan laluan ralat ini.','如果 int() 无法转换文字，就运行错误分支。'),
 T('Tell the user exactly what to enter next.','Beritahu pengguna dengan tepat apa yang perlu ditaip selepas ini.','明确告诉用户下一步应输入什么。')
];
function tutor(){const i=Math.min(TUTOR_LINES.length-1,Math.max(0,state.tutor));return `<div class="tutor-grid"><ol class="code-lines">${TUTOR_LINES.map((line,n)=>`<li ${n===i?'aria-current="step"':''}><code>${esc(line)}</code></li>`).join('')}</ol><div class="tutor-note"><span class="pill">${esc(tx(T('Line tutor','Tutor baris','逐行导师')))} · ${i+1}/${TUTOR_LINES.length}</span><h3>${esc(tx(TUTOR_NOTES[i]))}</h3><p>${esc(tx(T('Follow the highlighted line. Then move on.','Ikuti baris yang diserlahkan. Kemudian teruskan.','先看高亮的这一行，再看下一行。')))}</p><div class="actions"><button data-tutor="-1" ${i===0?'disabled':''}>← ${esc(tx(T('Previous','Sebelum','上一行')))}</button><button data-tutor="1" ${i===TUTOR_LINES.length-1?'disabled':''}>${esc(tx(T('Next line','Baris seterusnya','下一行')))} →</button></div></div></div>`;}
function readPage(){return `${card(T('Sam’s problem','Masalah Sam','Sam 遇到的问题'),`<p class="lead">${esc(tx(T('Sam wants to know whether there is enough time to ask the helpdesk. The program asks how many people are ahead and how many minutes are available. Each person, including Sam, needs 4 minutes.','Sam ingin tahu sama ada masa mencukupi untuk bertanya di meja bantuan. Atur cara meminta bilangan orang di depan dan minit yang tersedia. Setiap orang termasuk Sam memerlukan 4 minit.','Sam 想知道是否有足够时间询问服务台。程序要问前面有几个人、可用多少分钟。包括 Sam 在内，每人需要 4 分钟。')))}</p><div class="rule-grid"><div><span>01</span><b>${esc(tx(T('Ask','Tanya','提问')))}</b><p>${esc(tx(T('People ahead + minutes available','Orang di depan + minit tersedia','前面人数＋可用分钟')))}</p></div><div><span>02</span><b>${esc(tx(T('Check','Semak','检查')))}</b><p>${esc(tx(T('Both answers must be whole numbers, zero or more.','Kedua-dua jawapan mesti nombor bulat, sifar atau lebih.','两个答案都必须是大于或等于零的整数。')))}</p></div><div><span>03</span><b>${esc(tx(T('Decide','Putuskan','判断')))}</b><p>${esc(tx(T('Only valid answers lead to a time estimate and advice.','Hanya jawapan sah menghasilkan anggaran masa dan nasihat.','只有有效答案才会得到时间估计和建议。')))}</p></div></div>`, 'accent')}${card(T('Follow one worked example','Ikuti satu contoh lengkap','跟随一个完整示例'),`${paras(T('This smaller ticket program uses the same pattern: input → validate → inner decision → output. Click through each line.','Atur cara tiket yang lebih kecil ini menggunakan corak sama: input → sahkan → keputusan di dalam → output. Klik setiap baris.','这个较小的票务程序采用同一模式：输入→验证→内层判断→输出。逐行点击查看。'))}${tutor()}`)}`;}
function question(q){const value=state.answers[q.id],checked=state.checked[q.id];return `<section class="question" id="q-${q.id}"><div class="question-head"><span class="area ${q.area}">${q.area}</span><b>${esc(tx(q.prompt))}</b></div><div class="choices">${q.options.map((o,i)=>`<label class="choice ${String(value)===String(i)?'selected':''}"><input type="radio" name="q-${q.id}" data-question="${q.id}" value="${i}" ${String(value)===String(i)?'checked':''}>${esc(tx(o))}</label>`).join('')}</div><button data-check="${q.id}" ${value===undefined?'disabled':''}>${esc(tx(T('Check answer','Semak jawapan','检查答案')))}</button>${checked?`<p class="feedback ${Number(value)===q.answer?'right':'retry'}">${Number(value)===q.answer?esc(tx(T('Correct.','Betul.','正确。'))):esc(tx(T('Look again.','Lihat semula.','再想一想。')))} ${esc(tx(q.why))}</p>`:''}</section>`;}
function starterPage(){return `${card(T('What do you already know?','Apakah yang anda sudah tahu?','你已经知道什么？'),`${paras(T('Answer six short checks. The next page uses your first answers to suggest whether knowledge, skills or understanding needs most attention.','Jawab enam semakan ringkas. Halaman seterusnya menggunakan jawapan pertama anda untuk mencadangkan sama ada pengetahuan, kemahiran atau pemahaman memerlukan lebih perhatian.','回答六道简短问题。下一页会根据首次答案，提示知识、技能或理解哪方面最需要加强。'))}<div class="mini-legend"><span><b>K</b> ${esc(tx(T('facts and meanings','fakta dan maksud','事实与含义')))}</span><span><b>S</b> ${esc(tx(T('choosing and writing code','memilih dan menulis kod','选择和编写代码')))}</span><span><b>U</b> ${esc(tx(T('explaining why','menjelaskan sebab','解释原因')))}</span></div>${STARTER.map(question).join('')}`)}`;}
function counts(){const r={K:{right:0,tried:0},S:{right:0,tried:0},U:{right:0,tried:0}};STARTER.forEach(q=>{if(state.first[q.id]!==undefined){r[q.area].tried++;if(Number(state.first[q.id])===q.answer)r[q.area].right++;}});return r;}
function focus(){const c=counts();const all=Object.values(c).every(v=>v.tried===2);if(!all)return null;const misses=Object.fromEntries(Object.entries(c).map(([k,v])=>[k,2-v.right]));const max=Math.max(...Object.values(misses));return {areas:Object.keys(misses).filter(k=>misses[k]===max),misses,max};}
const AREA_DESCRIPTIONS={K:T('Clarify what invalid input, nesting and test types mean.','Jelaskan maksud input tidak sah, keputusan bersarang dan jenis ujian.','弄清无效输入、嵌套判断和测试类型的含义。'),S:T('Practise choosing conditions, writing indented code and running tests.','Berlatih memilih syarat, menulis kod berinden dan menjalankan ujian.','练习选择条件、编写缩进代码和运行测试。'),U:T('Explain why validation comes first and why the inner route runs only for valid data.','Jelaskan sebab pengesahan dibuat dahulu dan laluan di dalam hanya untuk data sah.','解释为什么先验证，以及为什么内层分支只处理有效数据。')};
function typesPage(){const c=counts(),f=focus();const names={K:tx(T('knowledge','pengetahuan','知识')),S:tx(T('skills','kemahiran','技能')),U:tx(T('understanding','pemahaman','理解'))};return `${card(T('Use your first answers','Gunakan jawapan pertama anda','查看你的首次答案'),`<p>${esc(tx(T('A correct answer you already knew is prior knowledge. A gap shows what to work on today. Changing an answer later helps you learn, but the starting picture stays visible.','Jawapan betul yang sudah anda tahu ialah pengetahuan sedia ada. Jurang menunjukkan apa yang perlu diusahakan hari ini. Menukar jawapan kemudian membantu pembelajaran, tetapi gambaran awal kekal.','你本来就会的正确答案属于已有知识。答错的地方提示今天要加强什么。之后改正有帮助，但起点记录会保留。')))}</p><div class="score-grid">${['K','S','U'].map(a=>`<div><span class="area ${a}">${a}</span><strong>${c[a].right}/${c[a].tried||2}</strong><span>${esc(names[a])}</span><small>${esc(tx(AREA_DESCRIPTIONS[a]))}</small></div>`).join('')}</div>${f?`<div class="focus-box"><b>${esc(tx(f.max===0?T('All six were correct. Choose a deeper challenge.','Semua enam betul. Pilih cabaran lebih mendalam.','六题全对。选择更深入的挑战。'):T('Your biggest learning focus','Fokus pembelajaran terbesar anda','你最需要加强的领域')))}</b><p>${f.max===0?esc(tx(T('Use the lesson to explain each choice and test edge cases.','Gunakan pelajaran untuk menjelaskan setiap pilihan dan menguji kes sempadan.','通过解释每个选择和测试边界情况来加深学习。'))):esc(tx(T('The most missed checks are in: ','Semakan paling banyak salah ialah: ','错误最多的检查属于：')))+f.areas.map(a=>esc(names[a])).join(', ')+'.'}</p>${f.max>0?`<p>${f.areas.map(a=>esc(tx(AREA_DESCRIPTIONS[a]))).join(' ')}</p>`:''}</div>`:`<div class="focus-box"><b>${esc(tx(T('Complete all six Do Now checks first.','Lengkapkan keenam-enam semakan dahulu.','先完成六道课前检查。')))}</b></div>`}`)}${card(T('Choose a useful next step','Pilih langkah seterusnya','选择下一步'),`<div class="three-grid">${[['K',T('I need to clarify a meaning.','Saya perlu menjelaskan maksud.','我需要弄清含义。'),T('Reread the rule and worked example.','Baca semula peraturan dan contoh.','重读规则和示例。')],['S',T('I need to practise a step.','Saya perlu berlatih satu langkah.','我需要练习一个步骤。'),T('Build the condition, run it, then fix it.','Bina syarat, jalankan, kemudian baiki.','编写条件、运行，再修正。')],['U',T('I need to explain a reason.','Saya perlu menjelaskan sebab.','我需要解释原因。'),T('Use a test case to say why a route runs.','Gunakan kes ujian untuk menjelaskan sebab laluan berjalan.','用测试用例解释为何运行某个分支。')]].map(([a,t,d])=>`<div class="step-card"><span class="area ${a}">${a}</span><b>${esc(tx(t))}</b><p>${esc(tx(d))}</p></div>`).join('')}</div>`)} `;}
const ORDER_BLOCKS=[
 T('Ask for people ahead and minutes available.','Tanya bilangan orang di depan dan minit tersedia.','询问前面人数与可用分钟。'),
 T('Check for blank, non-number or negative input.','Semak input kosong, bukan nombor atau negatif.','检查空白、非数字或负数输入。'),
 T('For valid inputs, calculate (people ahead + 1) × 4.','Bagi input sah, kira (orang di depan + 1) × 4.','对有效输入计算（前面人数 + 1）× 4。'),
 T('Inside the valid branch, compare total time with available time.','Dalam cabang sah, bandingkan jumlah masa dengan masa tersedia.','在有效输入分支内比较总时间和可用时间。')
];
function orderCard(){return `<div class="order-list">${state.order.map((n,i)=>`<div><span class="number">${i+1}</span><b>${esc(tx(ORDER_BLOCKS[n]))}</b><div><button data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Move up">↑</button><button data-move="${i}" data-dir="1" ${i===state.order.length-1?'disabled':''} aria-label="Move down">↓</button></div></div>`).join('')}</div><button data-order-check>${esc(tx(T('Check sequence','Semak urutan','检查顺序')))}</button>${state.orderChecked?`<p class="feedback ${state.order.every((n,i)=>n===i)?'right':'retry'}">${esc(tx(state.order.every((n,i)=>n===i)?T('Yes. Invalid answers stop before the calculation.','Ya. Jawapan tidak sah berhenti sebelum pengiraan.','对。无效答案在计算前就停止。'):T('Try again: checking must happen before calculation and advice.','Cuba lagi: semakan mesti dibuat sebelum pengiraan dan nasihat.','再试一次：先检查，再计算并给出建议。')))}</p>`:''}`;}
function editor(id){const value=state.code[id]??'';return `<div class="ide" id="ide-${id}"><div class="ide-bar"><b>Python 3 · ${esc(tx(T('Editor','Penyunting','编辑器')))}</b><div><button ${id==='main'&&state.page==='main1'?'data-primm-reset-main':`data-load="${id}"`}>${esc(tx(id==='main'&&state.page==='main1'?T('Reset nested starter','Tetap semula rangka bersarang','重置嵌套代码框架'):T('Reset scaffold','Tetap semula rangka','重置代码框架')))}</button><button data-download="${id}">↓ .py</button><button data-run="${id}" class="primary">▶ ${esc(tx(T('Run','Jalankan','运行')))}</button><button data-stop ${live?.id===id?'':'disabled'}>■ ${esc(tx(T('Stop','Henti','停止')))}</button></div></div><div class="ide-body"><div class="code-side"><label for="code-${id}" class="sr-only">Python code</label><textarea id="code-${id}" data-code="${id}" spellcheck="false" autocomplete="off" autocorrect="off" autocapitalize="off">${esc(value)}</textarea></div><div class="console-side"><div class="console-title">${esc(tx(T('Console · answer input() here','Konsol · jawab input() di sini','控制台 · 在这里回答 input()')))}</div><div class="console-log" id="console-${id}" aria-live="polite">${consoleHTML(id)}</div><form class="input-form" id="input-${id}" data-input="${id}" ${live?.id===id&&live.pending?'':'hidden'}><span>${esc(tx(T('Your answer','Jawapan anda','你的回答')))}</span><input name="answer" autocomplete="off" aria-label="Program input"><button type="submit">↵</button></form></div></div><div class="ide-foot">${esc(tx(T('Run your program. When input() asks a question, type in the console and press Enter. Ctrl/⌘+Enter also runs.','Jalankan atur cara. Apabila input() bertanya, taip di konsol dan tekan Enter. Ctrl/⌘+Enter juga menjalankan.','运行程序。出现 input() 问题时，在控制台输入并按回车。Ctrl/⌘+Enter 也可运行。')))}</div></div>`;}
function main1Page(){const worked=`people_text = input("People ahead of Sam: ")\navailable_text = input("Minutes available: ")\n\nif people_text.strip() == "" or available_text.strip() == "":\n    print("Enter a whole number. The answer cannot be blank.")`;return `${card(T('1A · Read the pattern before you code','1A · Baca corak sebelum menulis kod','1A · 编码前先看模式'),`<div class="two-grid"><div class="mini-card"><span class="pill">${esc(tx(T('The problem','Masalah','问题')))}</span><p>${esc(tx(T('An answer such as “two”, a blank, or −1 must not lead to a time estimate. A valid zero must be accepted.','Jawapan seperti “two”, kosong atau −1 tidak boleh menghasilkan anggaran masa. Sifar yang sah mesti diterima.','“two”、空白或 −1 不应产生时间估计。有效的 0 必须被接受。')))}</p><table><thead><tr><th>${esc(tx(T('Input','Input','输入')))}</th><th>${esc(tx(T('Program action','Tindakan atur cara','程序操作')))}</th></tr></thead><tbody><tr><td>2, 12</td><td>${esc(tx(T('Calculate and decide','Kira dan putuskan','计算并判断')))}</td></tr><tr><td>−1, 20</td><td>${esc(tx(T('Explain the correction; no estimate','Terangkan pembetulan; tiada anggaran','提示修正；不作估计')))}</td></tr><tr><td>two, 20</td><td>${esc(tx(T('Explain whole number; no estimate','Terangkan nombor bulat; tiada anggaran','提示输入整数；不作估计')))}</td></tr><tr><td>0, 4</td><td>${esc(tx(T('Valid: 4 minutes, ask now','Sah: 4 minit, tanya sekarang','有效：4 分钟，现在询问')))}</td></tr></tbody></table></div><div class="mini-card"><span class="pill">${esc(tx(T('Worked code: blank check','Kod contoh: semakan kosong','示例代码：空白检查')))}</span><pre class="code-sample"><code>${esc(worked)}</code></pre><p>${esc(tx(T('strip() removes spaces. The inner time decision belongs inside the valid branch, after conversion and calculation.','strip() membuang ruang. Keputusan masa di dalam berada dalam cabang sah, selepas penukaran dan pengiraan.','strip() 会去掉空格。内层时间判断应放在有效输入分支内，且在转换和计算之后。')))}</p></div></div>`)}${card(T('1B · Put the steps in order','1B · Susun langkah','1B · 排列步骤'),`${paras(T('Move each card. The program must check the input before it calculates or gives advice.','Alihkan setiap kad. Atur cara mesti menyemak input sebelum mengira atau memberi nasihat.','移动每张卡片。程序必须先检查输入，才能计算或给建议。'))}${orderCard()}`)}${card(T('1C · Complete Sam’s program','1C · Lengkapkan atur cara Sam','1C · 完成 Sam 的程序'),`<div class="program-layout"><div class="task-guide"><h3>${esc(tx(state.guided?T('Check two lines, then make one repair','Semak dua baris, kemudian baiki satu','检查两行，再修改一处'):T('Make these three repairs','Buat tiga pembaikan ini','完成三处修改')))}</h3>${state.guided?`<p class="small">${esc(tx(T('The first two lines are already written. Find them in the editor. Then replace the remaining False.','Dua baris pertama sudah ditulis. Cari dalam penyunting. Kemudian ganti False yang tinggal.','前两处代码已经写好。先在编辑器中找到它们，再替换剩下的 False。')))}</p>`:''}<ol><li>${esc(tx(state.guided?T('Find the completed negative-input check in your code.','Cari semakan input negatif yang sudah lengkap dalam kod.','在代码中找出已完成的负数检查。'):T('Replace the first False with a condition that catches a negative number in either input.','Ganti False pertama dengan syarat yang mengesan nombor negatif dalam mana-mana input.','把第一个 False 改成检查任意输入为负数的条件。')))}<pre><code>people_ahead &lt; 0 or minutes_available &lt; 0</code></pre></li><li>${esc(tx(state.guided?T('Find the completed time calculation, including Sam.','Cari pengiraan masa yang sudah lengkap, termasuk Sam.','找出已完成的时间计算，包括 Sam。'):T('Replace 0 with the calculation, including Sam.','Ganti 0 dengan pengiraan, termasuk Sam.','把 0 改成包含 Sam 的计算式。')))}<pre><code>(people_ahead + 1) * MINUTES_PER_PERSON</code></pre></li><li>${esc(tx(state.guided?T('Replace the one remaining False. Exactly enough time should count as enough.','Ganti satu False yang tinggal. Masa cukup tepat dikira mencukupi.','替换剩下的那个 False。时间刚好够也算够。'):T('Replace the second False so exactly enough time counts as enough.','Ganti False kedua supaya masa cukup tepat dikira mencukupi.','把第二个 False 改成比较条件，时间刚好够也算够。')))}<pre><code>total_minutes &lt;= minutes_available</code></pre></li></ol>${state.guided?`<div class="support-strip"><b>小提示</b> ${esc(tx(T('Copy one line at a time. Keep the spaces before each indented line.','Salin satu baris pada satu masa. Kekalkan ruang di hadapan setiap baris berinden.','一次复制一行，保留每行开头的空格。')))}</div>`:''}<p>${esc(tx(T('Run with 2 and 12, then 2 and 11. You should see different advice. Leave “Bad input” for Main Task 2.','Jalankan dengan 2 dan 12, kemudian 2 dan 11. Nasihat sepatutnya berbeza. Biarkan “Bad input” untuk Tugasan Utama 2.','先用 2、12 运行，再用 2、11 运行。应得到不同建议。“Bad input” 留到主要任务 2 再改。')))}</p></div>${editor('main')}</div>`)} `;}
function resultHTML(test){const result=state.tests[test.id];if(!result)return '<span class="not-run">—</span>';const cls=result.pass?'right':'retry';return `<div class="test-result ${cls}"><b>${esc(tx(result.pass?T('Pass','Lulus','通过'):T('Fix needed','Perlu dibaiki','需要修正')))}</b><details><summary>${esc(tx(T('See actual output','Lihat output sebenar','查看实际输出')))}</summary><pre>${esc(result.output||result.error||'No output')}</pre></details></div>`;}
function testTable(rows=TESTS){return `<div class="table-wrap"><table class="test-table"><thead><tr><th>${esc(tx(T('Test type','Jenis ujian','测试类型')))}</th><th>${esc(tx(T('People','Orang','人数')))}</th><th>${esc(tx(T('Minutes','Minit','分钟')))}</th><th>${esc(tx(T('Predict advice','Ramal nasihat','预测建议')))}</th><th>${esc(tx(T('Expected result','Hasil dijangka','预期结果')))}</th><th>${esc(tx(T('Run and compare','Jalankan dan bandingkan','运行并比较')))}</th></tr></thead><tbody>${rows.map(t=>`<tr><td><span class="test-kind">${esc(tx(t.kind))}</span></td><td><code>${esc(t.people)}</code></td><td><code>${esc(t.minutes)}</code></td><td><select data-predict="${t.id}"><option value="">${esc(tx(T('Choose…','Pilih…','请选择…')))}</option><option value="now" ${state.answers['predict_'+t.id]==='now'?'selected':''}>${esc(tx(T('Ask now','Tanya sekarang','现在询问')))}</option><option value="later" ${state.answers['predict_'+t.id]==='later'?'selected':''}>${esc(tx(T('Another time','Masa lain','另约时间')))}</option><option value="invalid" ${state.answers['predict_'+t.id]==='invalid'?'selected':''}>${esc(tx(T('Correction','Pembetulan','纠正提示')))}</option></select>${state.tests[t.id]&&state.answers['predict_'+t.id]?`<small class="${state.answers['predict_'+t.id]===t.route?'correct':'incorrect'}">${esc(tx(state.answers['predict_'+t.id]===t.route?T('Prediction fits','Ramalan sesuai','预测符合'):T('Check the rule','Semak peraturan','检查规则')))}</small>`:''}</td><td>${state.tests[t.id]?esc(tx(t.expected)):esc(tx(T('Reveal after running','Lihat selepas jalankan','运行后揭晓')))}</td><td><button data-test="${t.id}" ${batch||!state.answers['predict_'+t.id]?'disabled':''}>▶ ${esc(tx(T('Run test','Jalankan ujian','运行测试')))}</button>${resultHTML(t)}</td></tr>`).join('')}</tbody></table></div>`;}
function main2Page(){const done=TESTS.filter(t=>state.tests[t.id]).length,passes=TESTS.filter(t=>state.tests[t.id]?.pass).length;return `${card(T('2A · Plan what should happen','2A · Rancang hasilnya','2A · 预测结果'),`<div class="three-grid"><div class="step-card"><span class="pill">${esc(tx(T('Normal','Normal','正常')))}</span><b>2, 20</b><p>${esc(tx(T('A typical valid case: 12 minutes needed, so Sam can ask now.','Kes sah biasa: perlu 12 minit, jadi Sam boleh bertanya sekarang.','典型有效情况：需要 12 分钟，因此 Sam 可以现在询问。')))}</p></div><div class="step-card"><span class="pill">${esc(tx(T('Boundary','Sempadan','边界')))}</span><b>2, 11 → 12 → 13</b><p>${esc(tx(T('Try just below, exactly at and just above the 12-minute limit.','Cuba tepat di bawah, tepat pada dan tepat di atas had 12 minit.','测试 12 分钟界限的下方、正好和上方。')))}</p></div><div class="step-card"><span class="pill">${esc(tx(T('Erroneous','Ralat','错误')))}</span><b>−1 · two · blank</b><p>${esc(tx(T('Wrong input should receive a useful correction and no estimate.','Input salah perlu menerima pembetulan yang membantu dan tiada anggaran.','错误输入应得到有用的纠正提示，且不显示时间估计。')))}</p></div></div><p>${esc(tx(T('Choose your prediction in each row before you run it. “Run test” feeds those two answers to your current program and shows its actual output.','Pilih ramalan bagi setiap baris sebelum menjalankannya. “Jalankan ujian” memasukkan dua jawapan itu ke atur cara semasa dan memaparkan output sebenar.','先为每一行选择预测，再运行。“运行测试”会将两个答案输入当前程序并显示实际输出。')))}</p>`)}${card(T('2B · Run the planned tests','2B · Jalankan ujian terancang','2B · 运行计划好的测试'),`<div class="test-summary"><b>${done}/${TESTS.length} ${esc(tx(T('run','dijalankan','已运行')))}</b><b>${passes}/${TESTS.length} ${esc(tx(T('passing','lulus','通过')))}</b><button id="run-all" ${batch||!TESTS.every(t=>state.answers['predict_'+t.id])?'disabled':''}>▶ ${esc(tx(T('Run all planned tests','Jalankan semua ujian terancang','运行全部计划测试')))}</button></div>${testTable()}<p class="small">${esc(tx(T('Choose a prediction for each row to enable its Run test button. Predict all rows to enable Run all.','Pilih ramalan bagi setiap baris untuk mengaktifkan butang Jalankan ujian. Ramal semua baris untuk mengaktifkan Jalankan semua.','先为每一行作出预测，才能运行该测试。完成所有预测后可以运行全部。')))}</p><p class="small">${esc(tx(T('A “Fix needed” result points to a wrong route, wrong time or unhelpful error message. Open the actual output to see which.','Hasil “Perlu dibaiki” menunjukkan laluan salah, masa salah atau mesej ralat yang tidak membantu. Buka output sebenar untuk melihatnya.','“需要修正”表示分支、时间或错误提示有问题。展开实际输出查看原因。')))}</p>`)}${card(T('2C · Improve the error message','2C · Perbaiki mesej ralat','2C · 改进错误提示'),`<div class="two-grid"><div class="mini-card"><h3>${esc(tx(T('Before','Sebelum','修改前')))}</h3><pre class="code-sample"><code>print("Bad input")</code></pre><p>${esc(tx(T('This does not tell the user what was wrong or what to type next.','Ini tidak memberitahu pengguna apa yang salah atau apa yang perlu ditaip selepas ini.','这没有告诉用户错在哪里、下一步该输入什么。')))}</p></div><div class="mini-card"><h3>${esc(tx(T('Better messages','Mesej lebih baik','更好的提示')))}</h3><ul><li>${esc(tx(T('Blank: “Enter a whole number. The answer cannot be blank.”','Kosong: “Enter a whole number. The answer cannot be blank.”','空白：“Enter a whole number. The answer cannot be blank.”')))}</li><li>${esc(tx(T('Text/decimal: “Enter a whole number, such as 0 or 3.”','Teks/perpuluhan: “Enter a whole number, such as 0 or 3.”','文字/小数：“Enter a whole number, such as 0 or 3.”')))}</li><li>${esc(tx(T('Negative: “Enter zero or more. The number cannot be negative.”','Negatif: “Enter zero or more. The number cannot be negative.”','负数：“Enter zero or more. The number cannot be negative.”')))}</li></ul></div></div><p>${esc(tx(T('Edit the three “Bad input” lines in your program. Then rerun the erroneous rows. Keep valid zero working.','Sunting tiga baris “Bad input” dalam atur cara. Kemudian jalankan semula baris ralat. Pastikan sifar yang sah masih berfungsi.','修改程序中的三处“Bad input”，再重跑错误输入测试。确保有效的 0 仍可正常工作。')))}</p>${state.guided?`<button id="insert-messages">${esc(tx(T('Put the example messages into my code','Masukkan mesej contoh ke dalam kod saya','将示例提示放入我的代码')))}</button>`:''}<label class="field">${esc(tx(T('Which error message did you improve? What should the user enter instead?','Mesej ralat manakah yang anda perbaiki? Apakah yang patut pengguna taip?','你改进了哪条错误提示？用户应该输入什么？')))}<textarea data-answer="improvement" rows="2" placeholder="${esc(tx(T('Example: I changed the blank message. It now asks for a whole number.','Contoh: Saya menukar mesej kosong. Kini ia meminta nombor bulat.','例如：我修改了空白输入提示。它现在要求输入整数。')))}">${esc(state.answers.improvement||'')}</textarea></label>${state.guided?`<div class="word-choice"><button data-sentence="blank">${esc(tx(T('Blank → enter a whole number','Kosong → masukkan nombor bulat','空白→输入整数')))}</button><button data-sentence="negative">${esc(tx(T('Negative → enter zero or more','Negatif → masukkan sifar atau lebih','负数→输入零或以上')))}</button></div>`:''}`)}${card(T('Your program · edit and test again','Atur cara anda · sunting dan uji semula','你的程序 · 修改并重新测试'),`${editor('main')}`)}`;}
function challengePage(){return `${card(T('If you have extra time, go further','Jika ada masa tambahan, teruskan','如果还有时间，继续挑战'),`${paras(T('Complete these levels in order. They extend the same helpdesk program.','Lengkapkan aras ini mengikut urutan. Semuanya mengembangkan atur cara meja bantuan yang sama.','按顺序完成以下挑战。它们都继续改进同一个服务台程序。'))}<div class="three-grid"><div class="step-card"><span class="pill">${esc(tx(T('Level 1 · Explain','Aras 1 · Jelaskan','第 1 级 · 解释')))}</span><h3>${esc(tx(T('Explain three terms','Jelaskan tiga istilah','解释三个术语')))}</h3><table><tbody><tr><th>validation</th><td>${esc(tx(T('Checks input before using it','Menyemak input sebelum menggunakannya','使用前检查输入')))}</td></tr><tr><th>nested selection</th><td>${esc(tx(T('An if/else inside a valid route','if/else di dalam laluan sah','有效分支内的 if/else')))}</td></tr><tr><th>boundary</th><td>${esc(tx(T('The exact point where advice changes','Titik tepat apabila nasihat berubah','建议发生变化的临界值')))}</td></tr></tbody></table><label class="field">${esc(tx(T('Use one term in your own sentence.','Gunakan satu istilah dalam ayat anda sendiri.','用自己的话解释其中一个术语。')))}<textarea data-answer="challenge_terms" rows="3">${esc(state.answers.challenge_terms||'')}</textarea></label></div><div class="step-card"><span class="pill">${esc(tx(T('Level 2 · Trace','Aras 2 · Jejak','第 2 级 · 跟踪')))}</span><h3>${esc(tx(T('Follow a boundary case','Ikuti kes sempadan','跟踪边界情况')))}</h3><table><thead><tr><th>${esc(tx(T('Step','Langkah','步骤')))}</th><th>${esc(tx(T('Value / result','Nilai / hasil','值／结果')))}</th></tr></thead><tbody><tr><td>people_ahead</td><td>2</td></tr><tr><td>minutes_available</td><td>12</td></tr><tr><td>total_minutes</td><td>?</td></tr><tr><td>total_minutes &lt;= minutes_available</td><td>?</td></tr><tr><td>output</td><td>?</td></tr></tbody></table><p>${esc(tx(T('Find 12, True and “ask now” in a run.','Cari 12, True dan “ask now” dalam satu larian.','运行一次，找出 12、True 和“现在询问”。')))}</p></div><div class="step-card"><span class="pill">${esc(tx(T('Level 3 · Program','Aras 3 · Atur cara','第 3 级 · 编程')))}</span><h3>${esc(tx(T('Ask again after an error','Tanya semula selepas ralat','出错后重新提问')))}</h3><p>${esc(tx(T('Copy your working program into the challenge editor. Add a loop so an invalid answer asks again. Test a blank answer followed by a valid answer.','Salin atur cara yang berfungsi ke penyunting cabaran. Tambah gelung supaya input tidak sah ditanya semula. Uji jawapan kosong diikuti jawapan sah.','把可运行的程序复制到挑战编辑器。添加循环，使无效输入后重新提问。测试先输入空白，再输入有效答案。')))}</p><button id="copy-main">${esc(tx(T('Copy my program below','Salin atur cara saya di bawah','复制我的程序到下方')))}</button></div></div>`)}${card(T('Challenge Python workspace','Ruang Python cabaran','挑战 Python 工作区'),`${editor('challenge')}`)}`;}
const PHASES=[['new',T('New learning','Pembelajaran baharu','新学习'),T('New and difficult, but I am making progress.','Baharu dan sukar, tetapi saya semakin maju.','内容新且有难度，但我正在进步。')],['consolidating',T('Consolidating','Mengukuhkan','巩固'),T('I know the idea; practice is helping.','Saya tahu idea ini; latihan membantu.','我已经理解，练习正让我更熟练。')],['treading',T('Treading water','Terlalu mudah','原地踏步'),T('This is already easy; I need a harder challenge.','Ini sudah mudah; saya perlukan cabaran lebih sukar.','这已经很容易，我需要更大挑战。')],['drowning',T('Drowning / need help','Buntu / perlu bantuan','遇到困难／需要帮助'),T('I am stuck and need one step shown.','Saya buntu dan perlu satu langkah ditunjukkan.','我卡住了，需要有人示范一步。')]];
function pitPage(){const p=state.phase;const vals=['K','S','U'].map(a=>p[a]).filter(Boolean);const counts=Object.fromEntries(PHASES.map(([id])=>[id,vals.filter(v=>v===id).length]));const high=Math.max(0,...Object.values(counts));const majority=high>1?PHASES.filter(([id])=>counts[id]===high):[];return `${card(T('Where are you now?','Di manakah anda sekarang?','你现在处于什么阶段？'),`<p>${esc(tx(T('Choose a confidence phase for each part of today’s learning. The program shows the phase chosen most often. Your answers can differ across the three parts.','Pilih fasa keyakinan bagi setiap bahagian pembelajaran hari ini. Atur cara menunjukkan fasa yang paling kerap dipilih. Jawapan anda boleh berbeza bagi tiga bahagian.','为今天学习的每个部分选择一个信心阶段。程序会显示你选择最多的阶段。三个部分可以不同。')))}</p><div class="phase-rows">${[['K',T('Knowledge · invalid input, nesting and test types','Pengetahuan · input tidak sah, keputusan bersarang dan jenis ujian','知识 · 无效输入、嵌套与测试类型')],['S',T('Skills · validate, indent, run and improve','Kemahiran · sahkan, inden, jalankan dan perbaiki','技能 · 验证、缩进、运行与改进')],['U',T('Understanding · explain why and when','Pemahaman · jelaskan sebab dan bila','理解 · 解释原因与时机')]].map(([a,title])=>`<div><span class="area ${a}">${a}</span><b>${esc(tx(title))}</b><div class="phase-options">${PHASES.map(([id,label])=>`<label class="${p[a]===id?'selected':''}"><input type="radio" name="phase-${a}" data-phase="${a}" value="${id}" ${p[a]===id?'checked':''}>${esc(tx(label))}</label>`).join('')}</div></div>`).join('')}</div>${vals.length===3?`<div class="focus-box"><b>${majority.length===1?esc(tx(T('Your most selected phase: ','Fasa paling banyak dipilih: ','你选择最多的阶段：')))+esc(tx(majority[0][1])):esc(tx(T('Your answers are mixed. There is no single majority.','Jawapan anda bercampur. Tiada satu majoriti.','你的选择各不相同，没有单一多数。')))}</b><p>${esc(tx(T('This is your confidence check. A test can pass while the work still feels new or difficult.','Ini semakan keyakinan anda. Ujian boleh lulus walaupun kerja masih terasa baharu atau sukar.','这是你的信心检查。即使测试通过，学习也可能仍让你觉得新或困难。')))}</p></div>`:''}`)}`;}
function plenaryPage(){const qs=[{id:'p1',area:'K',prompt:T('Which input is valid for “people ahead”?','Input manakah sah untuk “orang di depan”?','“前面人数”的哪个输入有效？'),options:[T('0','0','0'),T('−2','−2','−2'),T('2.5','2.5','2.5')],answer:0,why:T('Zero is a valid whole number and means no one is ahead.','Sifar ialah nombor bulat sah dan bermaksud tiada orang di depan.','0 是有效整数，表示前面没有人。')},{id:'p2',area:'S',prompt:T('Which condition includes exactly enough time?','Syarat manakah termasuk masa yang cukup tepat?','哪个条件包含时间刚好够用？'),options:[T('total_minutes < minutes_available','total_minutes < minutes_available','total_minutes < minutes_available'),T('total_minutes <= minutes_available','total_minutes <= minutes_available','total_minutes <= minutes_available'),T('total_minutes == 0','total_minutes == 0','total_minutes == 0')],answer:1,why:T('<= includes the boundary where both times are equal.','<= termasuk sempadan apabila kedua-dua masa sama.','<= 包含两段时间相等的边界。')},{id:'p3',area:'U',prompt:T('A user enters “two”. What should the program do?','Pengguna menaip “two”. Apakah yang perlu dibuat oleh atur cara?','用户输入“two”。程序应该怎么做？'),options:[T('Show a correction and no estimate','Papar pembetulan dan tiada anggaran','显示纠正提示，不作估计'),T('Guess that they meant 2','Teka bahawa maksudnya 2','猜测用户想输入 2'),T('Print a time estimate anyway','Tetap paparkan anggaran masa','仍输出时间估计')],answer:0,why:T('The program must not invent a number or give misleading advice.','Atur cara tidak boleh mereka nombor atau memberi nasihat mengelirukan.','程序不能擅自猜数字或给出误导性建议。')}];return `${card(T('Show what you learned','Tunjukkan apa yang anda pelajari','展示你的学习成果'),`${qs.map(question).join('')}<label class="field">${esc(tx(T('In one sentence: why does your program check input before the time decision?','Dalam satu ayat: mengapa atur cara menyemak input sebelum keputusan masa?','用一句话说明：为什么程序要先检查输入，再判断时间？')))}<textarea data-answer="plenary_reason" rows="3" placeholder="${esc(tx(T('It checks first because…','Ia menyemak dahulu kerana…','先检查，是因为……')))}">${esc(state.answers.plenary_reason||'')}</textarea></label>`)}${card(T('Save your work and submit it','Simpan kerja dan hantar','保存并提交作品'),`<div class="submit-steps"><div><strong>1</strong><span>${esc(tx(T('Click Save as PDF. In the print window, choose Save as PDF.','Klik Simpan sebagai PDF. Dalam tetingkap cetak, pilih Simpan sebagai PDF.','点击“保存为 PDF”，在打印窗口选择保存为 PDF。')))}</span></div><div><strong>2</strong><span>${esc(tx(T('Upload that PDF to your Teams assignment.','Muat naik PDF itu ke tugasan Teams anda.','将 PDF 上传到 Teams 作业。')))}</span></div></div><button id="pdf" class="primary big">↓ ${esc(tx(T('Save as PDF','Simpan sebagai PDF','保存为 PDF')))}</button><details class="other-saves"><summary>${esc(tx(T('Other ways to keep a copy','Cara lain menyimpan salinan','其他保存方式')))}</summary><p>${esc(tx(T('Full backup saves your editable answers and code for another device. The .py button in the editor saves only Python code. The PDF is the file to submit in Teams.','Sandaran penuh menyimpan jawapan dan kod yang boleh disunting untuk peranti lain. Butang .py dalam penyunting hanya menyimpan kod Python. PDF ialah fail untuk dihantar dalam Teams.','完整备份保存可编辑答案和代码，供换设备使用。编辑器里的 .py 只保存 Python 代码。提交到 Teams 的是 PDF。')))}</p><button id="backup">${esc(tx(T('Save full backup','Simpan sandaran penuh','保存完整备份')))}</button><label class="file-label">${esc(tx(T('Load backup','Muatkan sandaran','加载备份')))}<input id="restore" type="file" accept="application/json,.json"></label></details>`)} `;}
function consoleHTML(id){if(live?.id===id){return esc(live.output||'')+(live.pending?`<span class="prompt">${esc(live.pending.prompt)}</span>`:'');}const last=state.runs.filter(r=>r.id===id).at(-1);if(!last)return esc(tx(T('Press Run. Answer each question here when it appears.','Tekan Jalankan. Jawab setiap soalan di sini apabila muncul.','点击运行。出现问题时在这里回答。')));return esc(last.output||'')+(last.error?`\n${esc(last.error)}`:'');}
function syncEditor(){document.querySelectorAll('.ide[id^="ide-"]').forEach(ide=>{const id=ide.id.slice(4),log=ide.querySelector('.console-log'),form=ide.querySelector('[data-input]'),stop=ide.querySelector('[data-stop]');if(log)log.innerHTML=consoleHTML(id);if(form)form.hidden=!(live?.id===id&&live.pending);if(stop)stop.disabled=live?.id!==id;});}
function stopRun(reason='stopped'){if(!live)return;const x=live;live=null;clearTimeout(x.timer);x.worker?.terminate();state.runs.push({id:x.id,at:new Date().toISOString(),code:x.code,output:x.output,error:x.error||reason,inputs:x.inputs});state.runs=state.runs.slice(-30);save();syncEditor();}
function armTimer(){if(!live)return;clearTimeout(live.timer);live.timer=setTimeout(()=>{if(live){live.error=tx(T('Time limit reached. Check for a loop that does not stop.','Had masa dicapai. Semak gelung yang tidak berhenti.','运行超时。检查是否有无法结束的循环。'));stopRun('timeout');}},30000);}
function runCode(id){if(live){say(T('Stop the current run first.','Hentikan larian semasa dahulu.','请先停止当前运行。'));return;}const code=state.code[id]||'';if(!code.trim()){say(T('Write or copy Python code first.','Tulis atau salin kod Python dahulu.','请先编写或复制 Python 代码。'));return;}const worker=new Worker('python-worker.js');live={id,code,worker,output:'',inputs:[],pending:null,error:'',timer:null};worker.onmessage=({data})=>{if(!live||live.worker!==worker)return;if(data.type==='output'){live.output+=data.text;syncEditor();}else if(data.type==='input'){live.pending={id:data.id,prompt:data.prompt};syncEditor();document.querySelector('#input-'+id+' input')?.focus();armTimer();}else if(data.type==='error'){live.error=data.error;stopRun('error');}else if(data.type==='done'){stopRun('');}};worker.onerror=()=>{if(live){live.error=tx(T('Python could not start. Open this page through its web link.','Python tidak dapat bermula. Buka halaman ini melalui pautan web.','Python 无法启动。请通过网页链接打开本页。'));stopRun('error');}};worker.postMessage({type:'run',code});armTimer();syncEditor();}
function submitInput(form){if(!live||!live.pending||form.dataset.input!==live.id)return;const input=form.elements.answer.value,pending=live.pending;live.inputs.push(input);live.output+=pending.prompt+input+'\n';live.pending=null;live.worker.postMessage({type:'input',id:pending.id,value:input});form.reset();armTimer();syncEditor();}
function checkTest(t,output,error){const lower=output.toLowerCase(),invalid=t.route==='invalid';let pass=false;if(!error){if(invalid){const specific=t.id==='negative'||t.id==='negative_time'?lower.includes('negative'):t.id==='blank'?lower.includes('blank'):lower.includes('whole number');pass=!lower.includes('estimated total')&&specific;}else{const expected=(Number(t.people)+1)*4;pass=lower.includes('estimated total: '+expected+' minutes')&&(t.route==='now'?lower.includes('ask the helpdesk now'):lower.includes('arrange another time'));}}return {pass,output,error,at:new Date().toISOString()};}
function autoTest(t){return new Promise(resolve=>{let inputs=[t.people==='[press Enter]'?'':t.people,t.minutes],output='',error='',finished=false;const worker=new Worker('python-worker.js');const timer=setTimeout(()=>finish('Timed out'),10000);function finish(err=''){if(finished)return;finished=true;clearTimeout(timer);worker.terminate();resolve(checkTest(t,output,error||err));}worker.onmessage=({data})=>{if(data.type==='output')output+=data.text;else if(data.type==='input')worker.postMessage({type:'input',id:data.id,value:inputs.shift()??''});else if(data.type==='error'){error=data.error;finish();}else if(data.type==='done')finish();};worker.onerror=()=>finish('Python worker could not start');worker.postMessage({type:'run',code:state.code.main||''});});}
async function runTests(ids){if(batch||live)return;batch=true;const current=state.page;render();for(const id of ids){const test=TESTS.find(t=>t.id===id);if(!test)continue;state.tests[id]=await autoTest(test);save();if(state.page===current)render();}batch=false;render();say(T('Tests finished. Open the actual output for any row that needs fixing.','Ujian selesai. Buka output sebenar bagi baris yang perlu dibaiki.','测试完成。展开需要修正的行查看实际输出。'));}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function report(){const c=counts();return `<div class="report"><h1>${esc(tx(LESSON.title))}</h1><p><b>${esc(tx(T('Student','Murid','学生')))}:</b> ${esc(state.name)} · <b>${esc(tx(T('Class','Kelas','班级')))}:</b> ${esc(state.className)}</p><h2>WAGBA</h2>${paras(LESSON.wagba)}<h2>${esc(tx(T('Starting checks','Semakan awal','起点检查')))}</h2><p>K ${c.K.right}/2 · S ${c.S.right}/2 · U ${c.U.right}/2</p><h2>${esc(tx(T('Python program','Atur cara Python','Python 程序')))}</h2><pre>${esc(state.code.main||'')}</pre><h2>${esc(tx(T('Planned tests','Ujian terancang','计划测试')))}</h2><table><thead><tr><th>${esc(tx(T('Input','Input','输入')))}</th><th>${esc(tx(T('Expected','Dijangka','预期')))}</th><th>${esc(tx(T('Result','Hasil','结果')))}</th><th>${esc(tx(T('Actual output','Output sebenar','实际输出')))}</th></tr></thead><tbody>${TESTS.map(t=>`<tr><td>${esc(t.people)}, ${esc(t.minutes)}</td><td>${esc(tx(t.expected))}</td><td>${state.tests[t.id]?esc(tx(state.tests[t.id].pass?T('Pass','Lulus','通过'):T('Fix needed','Perlu dibaiki','需要修正'))):'—'}</td><td>${esc((state.tests[t.id]?.output||state.tests[t.id]?.error||'—').slice(0,350))}</td></tr>`).join('')}</tbody></table><h2>${esc(tx(T('Improvement and reflection','Pembaikan dan refleksi','改进与反思')))}</h2><p>${esc(state.answers.improvement||'—')}</p><p>${esc(state.answers.plenary_reason||'—')}</p><p>K: ${esc(state.phase.K||'—')} · S: ${esc(state.phase.S||'—')} · U: ${esc(state.phase.U||'—')}</p>${state.code.challenge?.trim()?`<h2>${esc(tx(T('Further challenge code','Kod cabaran lanjutan','进阶挑战代码')))}</h2><pre>${esc(state.code.challenge)}</pre>`:''}</div>`;}
function importBackup(file){if(file.size>2000000){say(T('This backup is too large.','Sandaran ini terlalu besar.','备份文件过大。'));return;}file.text().then(s=>{const data=JSON.parse(s);if(data.app!==APP||!data.state)throw Error('Wrong file');if(state.started)download('helpdesk-previous-backup.json',JSON.stringify({app:APP,state},null,2),'application/json');state={...initial(),...data.state};if(!teacher){storageKey=notebookKey(state.name);localStorage.setItem(STORAGE_BASE+'-last',storageKey);}state.started=true;entry=false;save();render();say(T('Backup loaded.','Sandaran dimuatkan.','备份已加载。'));}).catch(()=>say(T('This is not a valid lesson backup. Your work was kept.','Ini bukan sandaran pelajaran yang sah. Kerja anda dikekalkan.','这不是有效的课程备份。你的作品已保留。')));}
document.addEventListener('submit',ev=>{if(ev.target.id==='entry'){ev.preventDefault();const form=ev.target;const nextName=form.elements.name.value.trim().slice(0,100),nextClass=form.elements.className.value.trim().slice(0,60);if(!nextName||!nextClass)return;if(!teacher){const nextKey=notebookKey(nextName);if(nextKey!==storageKey){save();let saved=null;try{saved=JSON.parse(localStorage.getItem(nextKey)||'null');}catch{}const currentLang=state.lang;state=saved?.app===APP&&saved.state?{...initial(),...saved.state}:initial();if(!saved)state.lang=currentLang;storageKey=nextKey;}localStorage.setItem(STORAGE_BASE+'-last',storageKey);}state.name=nextName;state.className=nextClass;state.guided=teacher?state.guided:matchKai(state.name);if(state.guided&&state.code.main===SCAFFOLD)state.code.main=guidedScaffold();state.started=true;entry=false;save();render();window.scrollTo(0,0);}else if(ev.target.matches('[data-input]')){ev.preventDefault();submitInput(ev.target);}});
document.addEventListener('change',ev=>{const e=ev.target;if(e.id==='language'){state.lang=e.value;save();render();}else if(e.id==='restore'&&e.files[0])importBackup(e.files[0]);else if(e.dataset.question){const q=STARTER.find(x=>x.id===e.dataset.question);state.answers[e.dataset.question]=e.value;if(q&&state.first[q.id]===undefined)state.first[q.id]=e.value;delete state.checked[e.dataset.question];save();render();}else if(e.dataset.predict){state.answers['predict_'+e.dataset.predict]=e.value;save();render();}else if(e.dataset.phase){state.phase[e.dataset.phase]=e.value;save();render();}});
document.addEventListener('input',ev=>{const e=ev.target;if(e.dataset.code){state.code[e.dataset.code]=e.value.slice(0,20000);if(e.dataset.code==='main')state.tests={};save();}else if(e.dataset.answer){state.answers[e.dataset.answer]=e.value.slice(0,6000);save();}});
document.addEventListener('keydown',ev=>{const e=ev.target;if(!e.matches('textarea[data-code]'))return;if(ev.key==='Tab'){ev.preventDefault();e.setRangeText('    ',e.selectionStart,e.selectionEnd,'end');e.dispatchEvent(new Event('input',{bubbles:true}));}else if(ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();runCode(e.dataset.code);}else if(ev.key==='Enter'&&!ev.shiftKey){ev.preventDefault();const line=e.value.slice(0,e.selectionStart).split('\n').at(-1),indent=(line.match(/^ */)||[''])[0]+(line.trimEnd().endsWith(':')?'    ':'');e.setRangeText('\n'+indent,e.selectionStart,e.selectionEnd,'end');e.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page){if(live)stopRun('stopped');state.page=b.dataset.page;save();render();window.scrollTo(0,0);document.getElementById('page-title')?.focus();return;}if(b.id==='home'){entry=true;if(live)stopRun('stopped');render();window.scrollTo(0,0);}else if(b.id==='toggle-guided'){state.guided=!state.guided;save();render();}else if(b.dataset.tutor){state.tutor=Math.max(0,Math.min(TUTOR_LINES.length-1,state.tutor+Number(b.dataset.tutor)));save();document.querySelector('.tutor-grid').outerHTML=tutor();}else if(b.dataset.check){state.checked[b.dataset.check]=true;save();const q=[...STARTER,{id:'p1',area:'K',prompt:T('Which input is valid for “people ahead”?','Input manakah sah untuk “orang di depan”?','“前面人数”的哪个输入有效？'),options:[T('0','0','0'),T('−2','−2','−2'),T('2.5','2.5','2.5')],answer:0,why:T('Zero is valid.','Sifar sah.','零有效。')},{id:'p2',area:'S',prompt:T('Which condition includes exactly enough time?','Syarat manakah termasuk masa yang cukup tepat?','哪个条件包含时间刚好够用？'),options:[T('total_minutes < minutes_available','total_minutes < minutes_available','total_minutes < minutes_available'),T('total_minutes <= minutes_available','total_minutes <= minutes_available','total_minutes <= minutes_available'),T('total_minutes == 0','total_minutes == 0','total_minutes == 0')],answer:1,why:T('<= includes equality.','<= termasuk kesamaan.','<= 包含相等。')},{id:'p3',area:'U',prompt:T('A user enters “two”. What should the program do?','Pengguna menaip “two”. Apakah yang perlu dibuat oleh atur cara?','用户输入“two”。程序应该怎么做？'),options:[T('Show a correction and no estimate','Papar pembetulan dan tiada anggaran','显示纠正提示，不作估计'),T('Guess that they meant 2','Teka bahawa maksudnya 2','猜测用户想输入 2'),T('Print a time estimate anyway','Tetap paparkan anggaran masa','仍输出时间估计')],answer:0,why:T('Do not guess or mislead.','Jangan teka atau mengelirukan.','不要猜测或误导。')}].find(x=>x.id===b.dataset.check);if(q)document.getElementById('q-'+q.id).outerHTML=question(q);}else if(b.dataset.move!==undefined){const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[state.order[i],state.order[j]]=[state.order[j],state.order[i]];state.orderChecked=false;save();render();}else if(b.hasAttribute('data-order-check')){state.orderChecked=true;save();render();}else if(b.dataset.run){runCode(b.dataset.run);}else if(b.hasAttribute('data-stop'))stopRun('stopped');else if(b.dataset.load){if(!confirm(tx(T('Replace the code in this editor with the scaffold? Save .py first if needed.','Ganti kod dalam penyunting dengan rangka? Simpan .py dahulu jika perlu.','用代码框架替换当前代码？如需保留，请先保存 .py。'))))return;state.code[b.dataset.load]=b.dataset.load==='main'?(state.guided?guidedScaffold():SCAFFOLD):b.dataset.load==='primm_model'?PRIMM_NESTED_CODE:b.dataset.load==='primm_validation'?PRIMM_VALIDATION_CODE:'# Write your challenge code here\n';if(b.dataset.load==='main')state.tests={};save();render();}else if(b.dataset.download)download('helpdesk-'+b.dataset.download+'.py',state.code[b.dataset.download]||'','text/x-python');else if(b.dataset.test)runTests([b.dataset.test]);else if(b.id==='run-all')runTests(TESTS.map(t=>t.id));else if(b.id==='insert-messages'){let i=0;const replacements=['Enter a whole number. The answer cannot be blank.','Enter zero or more. The number cannot be negative.','Enter a whole number, such as 0 or 3.'];state.code.main=(state.code.main||'').replace(/Bad input/g,()=>replacements[i++]||'Bad input');state.tests={};save();render();say(T('Messages inserted. Rerun the three erroneous tests.','Mesej dimasukkan. Jalankan semula tiga ujian ralat.','提示已插入。请重新运行三个错误输入测试。'));}else if(b.dataset.sentence){state.answers.improvement=b.dataset.sentence==='blank'?'I changed the blank message. Enter a whole number.':'I changed the negative message. Enter zero or more.';save();render();}else if(b.id==='copy-main'){state.code.challenge=state.code.main;save();render();}else if(b.id==='pdf'){document.getElementById('print-report').innerHTML=report();window.print();}else if(b.id==='backup')download('helpdesk-full-backup.json',JSON.stringify({app:APP,state},null,2),'application/json');});
window.addEventListener('pagehide',save);
render();
